<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {request} from '@/api/client'
import {uiText} from '@/i18n'
import type {FileView} from '@/types/api'
const props=defineProps<{file?:FileView}>(),emit=defineEmits<{changed:[]}>()
const usage=ref<{files:number;totalBytes:number;trashBytes:number}>(),rows=ref<FileView[]>([]),refs=ref<{kind:string;count:number}[]>([])
const page=ref(0),total=ref(0),busy=ref(false),loading=ref(true),error=ref(''),purge=ref<FileView>(),confirmation=ref('');let active=true,version=0
onBeforeUnmount(()=>{active=false;version++})
const size=(n:number)=>(n/1048576).toFixed(2)+' MB'
async function load(){const v=++version;loading.value=true;error.value='';try{const [u,t,r]=await Promise.all([request<typeof usage.value>('/files/usage'),request<{items:FileView[];total:number}>('/files/trash?page='+page.value),props.file?request<typeof refs.value>('/files/'+props.file.id+'/references'):Promise.resolve([])]);if(active&&version===v){usage.value=u;rows.value=t.items;total.value=t.total;refs.value=r;const last=Math.max(0,Math.ceil(t.total/24)-1);if(page.value>last){page.value=last;await load()}}}catch(e){if(active&&version===v)error.value=(e as Error).message}finally{if(active&&version===v)loading.value=false}}
async function change(file:FileView,action:string){if(busy.value||loading.value)return;busy.value=true;error.value='';try{await request('/files/'+file.id+'/lifecycle',{method:'POST',body:JSON.stringify({action,confirmName:action==='PURGE'?confirmation.value:null})});if(active){purge.value=undefined;confirmation.value='';emit('changed');await load()}}catch(e){if(active)error.value=(e as Error).message}finally{if(active)busy.value=false}}
async function turn(delta:number){if(busy.value||loading.value)return;page.value+=delta;await load()}
onMounted(load)
</script>
<template><section class="storage-panel" :aria-busy="busy||loading"><p v-if="error" class="inline-alert inline-alert--error" role="alert">{{uiText(error)}} <button class="table-action" :disabled="busy||loading" @click="load">{{uiText('重试')}}</button></p><p v-if="usage">{{uiText('我的素材空间')}} · {{usage.files}} {{uiText('个文件')}} · {{size(usage.totalBytes)}}<br/><small>{{uiText('回收站占用')}} {{size(usage.trashBytes)}}</small></p><template v-if="file"><h3>{{file.originalName}}</h3><p v-if="refs.length">{{uiText('仍被以下内容引用')}}</p><ul><li v-for="r in refs" :key="r.kind">{{uiText(r.kind)}} · {{r.count}}</li></ul><button class="button button--ghost" :disabled="busy||loading||!!error||!!refs.length" @click="change(file,'TRASH')">{{uiText('移入回收站')}}</button></template><h3>{{uiText('素材回收站')}}</h3><p class="field-hint">{{uiText('恢复后可继续使用。永久删除需要输入文件名，仍被引用的文件不能删除。')}}</p><p v-if="!loading&&!rows.length">{{uiText('回收站为空')}}</p><article v-for="row in rows" :key="row.id"><div><strong>{{row.originalName}}</strong><small>{{size(row.sizeBytes)}}</small></div><button class="table-action" :disabled="busy||loading" @click="change(row,'RESTORE')">{{uiText('恢复')}}</button><button class="table-action" :disabled="busy||loading" @click="purge=row;confirmation=''">{{uiText('永久删除')}}</button></article><form v-if="purge" @submit.prevent="change(purge,'PURGE')"><label>{{uiText('输入完整文件名确认永久删除')}}<strong>{{purge.originalName}}</strong><input v-model="confirmation" class="field-input" :disabled="busy" autocomplete="off" /></label><div><button class="button button--ghost" type="button" :disabled="busy" @click="purge=undefined;confirmation=''">{{uiText('取消')}}</button><button class="button button--dark" :disabled="busy||loading||confirmation!==purge.originalName">{{uiText('永久删除')}}</button></div></form><nav><button class="table-action" :disabled="!page||busy||loading" @click="turn(-1)">{{uiText('上一页')}}</button><span>{{page+1}} / {{Math.max(1,Math.ceil(total/24))}}</span><button class="table-action" :disabled="(page+1)*24>=total||busy||loading" @click="turn(1)">{{uiText('下一页')}}</button></nav></section></template>
<style scoped>.storage-panel{display:grid;gap:18px}.storage-panel article,.storage-panel nav{display:flex;align-items:center;gap:16px;padding:14px 0;border-bottom:1px solid var(--line)}article>div{flex:1;min-width:0;overflow-wrap:anywhere}small{display:block;color:var(--muted);margin-top:6px}form{display:grid;gap:16px;border:1px solid var(--line);padding:20px;border-radius:12px}label strong{display:block;margin:10px 0}form>div{display:flex;gap:12px}</style>
